import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, texture, mul, add } from 'three/tsl';
import { gsap } from 'gsap';
import { createText } from '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {string} [imageUrl]
 * @property {any} [depthMapUrl]
 * @property {any} [meshUrl]
 * @property {Array<Object>} [textContent]
 * @property {Array<{name:string,params:any,trigger:string}>} [cinematicPrimitives]
 * @property {Object} [intent]
 */

/**
 * @typedef {Object} NodeContext
 * @property {any} THREE
 * @property {Object} textureLoader
 * @property {Object} glbLoader
 * @property {Object} [videoLoader]
 * @property {Object} fontAtlas
 * @property {Object} primitives
 * @property {Function} emit
 * @property {string} [tier]
 */

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Vector2 } = ctx.THREE;

  // Root container (position/rotation/scale already applied by the adapter)
  const root = new Group();

  // -------------------------------------------------------------------------
  // Text – headline “Journal”
  // -------------------------------------------------------------------------
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of textItems) {
    const txt = ctx.fontAtlas.createText(item.text ?? 'Journal', {
      fontSize: item.typography?.fontSize ?? 96,
      color: config.visual?.colors?.ink ?? '#16161d',
      align: 'center',
    });
    // Center the text on the plane (z = 0.01 to avoid z‑fighting)
    txt.position.set(0, 0.1, 0.01);
    root.add(txt);
  }

  // -------------------------------------------------------------------------
  // Textured plane (sprite‑like)
  // -------------------------------------------------------------------------
  const plane = new Mesh();
  // Atlas region – using the supplied size to keep aspect ratio
  const REGION_W = 512;
  const REGION_H = 320;
  const aspect = REGION_W / REGION_H;
  const geometry = new PlaneGeometry(aspect, 1, 1, 1);
  plane.geometry = geometry;

  // Basic node material – will receive a texture node once loaded
  const material = new MeshBasicNodeMaterial();
  material.transparent = true;
  plane.material = material;

  // Load the texture (async, but we keep the node synchronous)
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      // Build a texture node that samples only the atlas region
      // UV transformation: uv * scale + offset
      const uvNode = uv();
      const texNode = texture(tex, add(mul(uvNode, new Vector2(REGION_W / tex.image.width, REGION_H / tex.image.height)), new Vector2(0, 0)));
      material.colorNode = texNode; // MeshBasicNodeMaterial uses colorNode for simple sprite
      material.needsUpdate = true;
    });
  }

  // Billboarding – update handler points the plane toward the camera each frame
  root.userData.handlers = {
    update: (delta, elapsed, camera) => {
      // Only rotate the plane, keep its position/scale untouched
      const lookAt = camera.position.clone();
      lookAt.sub(root.position).normalize();
      const quat = root.quaternion;
      quat.setFromUnitVectors(new ctx.THREE.Vector3(0, 0, 1), lookAt);
    },
  };

  // -------------------------------------------------------------------------
  // Apply any cinematic primitives declared in the config (none expected)
  // -------------------------------------------------------------------------
  const primitiveInstances = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      if (ctx.primitives[prim.name]) {
        const instance = ctx.primitives[prim.name](root, prim.params);
        primitiveInstances.push(instance);
        // bind trigger if needed – primitive API handles its own events
        // (the spec does not require us to wire triggers manually)
      }
    }
  }

  // -------------------------------------------------------------------------
  // Cleanup
  // -------------------------------------------------------------------------
  root.userData.cleanup = () => {
    // dispose geometry & material
    if (plane.geometry) plane.geometry.dispose();
    if (plane.material) plane.material.dispose();

    // kill any GSAP timelines (none are created here, but guard anyway)
    if (typeof gsap !== 'undefined' && gsap.globalTimeline) {
      gsap.globalTimeline.clear();
    }

    // cleanup primitives
    for (const inst of primitiveInstances) {
      if (inst && typeof inst.cleanup === 'function') {
        inst.cleanup();
      }
    }

    // clear handlers reference
    root.userData.handlers = {};
  };

  // Add the plane as a child of the root group (render order after text)
  root.add(plane);

  return root;
}
